Q: Get a file name with extension from a folder and use it for opening A: <p>Here is a simple example of how to manipulate the strings.</p>
<pre class="lang-c prettyprint-override"><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;string.h&gt;


/*  This function, ComposeFileName, assembles a path to a file from:

        a directory given by path in Directory,

        the base name of a file given in Path, and

        a file name extension in Extension.

    Inputs:

        Directory is expected to be a path (relative or absolute) to a directory
        and is used without change.  It does not need to contain a trailing
        slash.

        Path is expected to be a path to a file (possibly just a bare file
        name).  If it contains slashes, only the last path component is used.
        Any trailing extension is removed.  For example:

            If Path contains &quot;/abc/def.pdq&quot;, only &quot;def&quot; is used.

            If Path contains &quot;foo.bar.baz&quot;, only &quot;foo.bar&quot; is used.

        Extension contains a file name extension, without a preceding period,
        such as &quot;bin&quot; or &quot;cpp&quot;.

    Output:

        A pointer to dynamically allocated space containing the constructed
        path, with a null terminating character, is returned.

        This memory should be freed when it is no longer needed.
*/
static char *ComposeFileName(
    const char *Directory, const char *Path, const char *Extension)
{
    /*  Find the last component of Path, and isolate the part before any
        extension.
    */
    const char *Name = Path;
    size_t NameLength;
    {
        const char *t = 0;
        const char *p;
        for (p = Path; *p; ++p)
        {
            if (*p == '/')
                Name = p+1;
            if (*p == '.')
                t = p;
        }
        if (!t)
            t = p;
        NameLength = t - Name;
    }
    /*  Now:

            If Path contains any '/', Name points just beyond it.
            Otherwise, Name points to the start of Path.

            NameLength contains the length of the name portion of the string,
            without the extension.
    */

    /*  Calculate how much space we need, including for the '/' between the
        directory and the file name, the '.' between the name and the extension,
        and the terminating null character.
    */
    size_t DirectoryLength = strlen(Directory);
    size_t ExtensionLength = strlen(Extension);
    size_t s = DirectoryLength + 1 + NameLength + 1 + ExtensionLength + 1;

    char *Result = malloc(s);
    if (!Result)
    {
        fprintf(stderr, &quot;Error, unable to allocate %zu bytes for new path.\n&quot;,
            s);
        exit(EXIT_FAILURE);
    }

    //  Copy the directory.
    memcpy(Result, Directory, DirectoryLength);
    char *p = Result + DirectoryLength;

    //  Append a '/' to the directory.
    *p++ = '/';

    //  Append the name.
    memcpy(p, Name, NameLength);
    p += NameLength;

    //  Append a '.'.
    *p++ = '.';

    //  Append the extension.
    memcpy(p, Extension, ExtensionLength);
    p += ExtensionLength;

    //  Terminate the string with a null character.
    *p = '\0';

    //  Return the result.
    return Result;
}


static void Test(
    const char *Directory, const char *Path, const char *Extension)
{
    char *T = ComposeFileName(Directory, Path, Extension);

    printf(&quot;Directory %s, path %s, extension %s -&gt; %s.\n&quot;,
        Directory, Path, Extension, T);

    free(T);
}


int main(void)
{
    Test(&quot;/directory&quot;, &quot;/abc/def.xyz&quot;, &quot;BIN&quot;);
    Test(&quot;directory&quot;, &quot;/abc/def&quot;, &quot;BIN&quot;);
    Test(&quot;./directory/foo&quot;, &quot;/abc/def.x.yz&quot;, &quot;BIN&quot;);
}
</code></pre>
